package com.atlasiq.enterprise;
import jakarta.enterprise.context.ApplicationScoped;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
@ApplicationScoped public class LicenseService {public License verify(String token,PublicKey key){try{String[] p=token.split("\\.");if(p.length!=2)throw new IllegalArgumentException("invalid license");byte[] body=Base64.getUrlDecoder().decode(p[0]),sig=Base64.getUrlDecoder().decode(p[1]);Signature s=Signature.getInstance("SHA256withRSA");s.initVerify(key);s.update(body);if(!s.verify(sig))throw new SecurityException("invalid license signature");String[] v=new String(body,StandardCharsets.UTF_8).split("\\|");var x=new License(v[0],v[1],LocalDate.parse(v[2]),Set.of(v[3].split(",")));if(x.expires().isBefore(LocalDate.now()))throw new SecurityException("license expired");return x;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}public record License(String organizationId,String plan,LocalDate expires,Set<String> features){}}
